function playerCard(p:PlayerCard,small=false){return '<article class="player-card rarity-'+p.rarity.toLowerCase()+(small?' compact':'')+'"><div class="player-card-top"><small style="color:'+color(p.rarity)+'">'+rarity(p.rarity)+'</small><b>'+(p.isGoalie?'🥅':'🏒')+'</b></div><div class="player-avatar">'+(p.isGoalie?'🧤':'🏒')+'</div><strong>'+esc(p.name)+'</strong><div class="stats-grid">'+(p.isGoalie?'<span>РЕАКЦИЯ <b>'+(p.reaction/10).toFixed(1)+'</b></span>':'<span>СКОРОСТЬ <b>'+(p.speed/10).toFixed(1)+'</b></span>')+'<span>ЛОВКОСТЬ <b>'+p.agility+'</b></span><span>СИЛА <b>'+p.strength+'</b></span><span>ВЫНОСЛИВОСТЬ <b>'+p.stamina+'</b></span></div></article>';}
