 const homePct=stamina(current.homeUseGoalie2?current.homeGoalie2Stamina:current.homeGoalie1Stamina,current.homeUseGoalie2?current.homeGoalie2Max:current.homeGoalie1Max);
 const awayPct=stamina(current.awayUseGoalie2?current.awayGoalie2Stamina:current.awayGoalie1Stamina,current.awayUseGoalie2?current.awayGoalie2Max:current.awayGoalie1Max);
 const result=fin?(current.homeScore>current.awayScore?'ПОБЕДА':current.homeScore<current.awayScore?'ПОРАЖЕНИЕ':'НИЧЬЯ'):'МАТЧ В ПРОЦЕССЕ';
