 '<section class="rink-wrap"><div class="rink-head"><span>ЛЕДОВАЯ АРЕНА · '+esc(team.stadium.name).toUpperCase()+'</span><span>🏒 5 НА 5</span></div>'+rinkVisual()+'</section>'+
 '<section class="ice-status"><div class="ice-status-player"><span class="status-crest" style="background:'+esc(matchHome?.club.primaryColor||'#168de0')+'">🧤</span><div><small>ВОРОТЧИК · ХОЗЯЕВА</small><b>'+esc(hGoalie?.name||'—')+'</b><div class="stamina-track"><i style="width:'+homePct+'%"></i></div></div><strong>'+homePct+'%</strong></div><div class="ice-status-player"><span class="status-crest away" style="background:'+esc(rival.club.primaryColor||'#e46b48')+'">🧤</span><div><small>ВОРОТЧИК · ГОСТИ</small><b>'+esc(aGoalie?.name||'—')+'</b><div class="stamina-track"><i style="width:'+awayPct+'%"></i></div></div><strong>'+awayPct+'%</strong></div></section>'+
 '<div class="below"><section class="panel controls"><div class="panel-title">УПРАВЛЕНИЕ МАТЧЕМ</div><p>'+(fin?'Матч окончен. Награда зачислена.':'Матч идёт непрерывно: игроки двигаются, разыгрывают шайбу и атакуют без пошаговых смен.')+'</p><button class="primary" data-action="pause-match" '+(fin?'disabled':'')+'>'+(liveRuntime?.paused?'▶ Продолжить матч':'Ⅱ Пауза матча')+'</button>'+(fin?'<button class="secondary" data-action="new-match">↻ Новый матч</button><button class="secondary" data-screen="office">🏠 В офис</button>':'')+'<div class="progress"><div style="width:'+(played/15*100)+'%"></div></div><small>ПРОГРЕСС · '+played+' / 15 СМЕН</small></section><section class="panel"><div class="panel-title">ХОД МАТЧА <span class="live-dot">● LIVE</span></div><div class="events">'+(match!.log.slice(-12).reverse().map((x,i)=>'<div class="event '+(i===0?'latest':'')+'"><i></i><span>'+esc(x)+'</span></div>').join('')||'<p>Матч готов.</p>')+'</div></section></div>';
